 67	function createEmptyTabState(): TabState {
 68	  return {
 69	    sessionId: null,
 70	    messages: [],
 71	    peerStatus: null,
 72	    isStreaming: false,
 73	    isCompacting: false,
 74	    lastStatus: null,
 75	    tokenUsage: createEmptyTokenUsage(),
