 86	/** Copy all mirrored fields from active tab → flat state (for component reads). */
 87	function syncFlatStateFromTab(draft: ChatState, tab: 'think' | 'do') {
 88	  draft.sessionId = draft[tab].sessionId;
 89	  draft.messages = draft[tab].messages;
 90	  draft.isStreaming = draft[tab].isStreaming;
 91	  draft.isCompacting = draft[tab].isCompacting;
 92	  draft.lastStatus = draft[tab].lastStatus;
 93	  draft.tokenUsage = draft[tab].tokenUsage;
 94	  draft.activeTokenUsage = draft[tab].activeTokenUsage;
 95	  draft.pendingInput = draft[tab].pendingInput;
 96	  draft.planMode = draft[tab].planMode;
 97	  draft.pendingQuestion = draft[tab].pendingQuestion;
 98	  draft.title = draft[tab].title;
 99	  draft.titleSource = draft[tab].titleSource;
100	  draft.inputDraft = draft[tab].inputDraft;
101	}
102	
103	/** Copy all mirrored fields from flat state → tab (for tab switching). */
104	function syncTabStateFromFlat(draft: ChatState, tab: 'think' | 'do') {
105	  draft[tab].sessionId = draft.sessionId;
106	  draft[tab].messages = draft.messages;
107	  draft[tab].isStreaming = draft.isStreaming;
108	  draft[tab].isCompacting = draft.isCompacting;
109	  draft[tab].lastStatus = draft.lastStatus;
110	  draft[tab].tokenUsage = draft.tokenUsage;
111	  draft[tab].activeTokenUsage = draft.activeTokenUsage;
112	  draft[tab].pendingInput = draft.pendingInput;
113	  draft[tab].planMode = draft.planMode;
114	  draft[tab].pendingQuestion = draft.pendingQuestion;
115	  draft[tab].title = draft.title;
116	  draft[tab].titleSource = draft.titleSource;
117	  draft[tab].inputDraft = draft.inputDraft;
118	}
