209	let handshakeTimer: ReturnType<typeof setTimeout> | null = null;
210	
211	function clearHandshakeTimer() {
212	  if (handshakeTimer) {
213	    clearTimeout(handshakeTimer);
214	    handshakeTimer = null;
215	  }
216	}
217	
218	function clearAllInlineErrors(state: { messages: ChatMessage[] }): void {
219	  for (const msg of state.messages) {
220	    if (msg.inlineError) {
221	      msg.inlineError = undefined;
222	    }
223	  }
224	}
225	
226	function doSend(state: ChatState, content: string | ContentPart[], model: string) {
227	  const { sessionId } = state;
228	  const { thinkingEnabled } = useSettingsStore.getState();
229	
230	  clearHandshakeTimer();
231	  handshakeTimer = setTimeout(() => {
232	    const s = useChatStore.getState();
233	    if (s.isStreaming && !s.handshakeReceived) {
234	      bridge.abortChat();
235	      s.processEvent({
236	        type: "error",
237	        code: "HANDSHAKE_TIMEOUT",
238	        message: "Connection timed out.",
239	        phase: "runtime",
240	      });
241	    }
242	  }, HANDSHAKE_TIMEOUT_MS);
243	
244	  bridge.streamChat(content, model, thinkingEnabled, sessionId ?? undefined, state.activeTab);
245	}
246	
247	export const useChatStore = create<ChatState>((set, get) => ({
248	  sessionId: null,
249	  messages: [],
250	  isStreaming: false,
251	  isCompacting: false,
252	  handshakeReceived: false,
253	  draftMedia: [],
254	  lastStatus: null,
255	  tokenUsage: createEmptyTokenUsage(),
256	  activeTokenUsage: createEmptyTokenUsage(),
257	  pendingInput: null,
258	  queue: [],
259	  pendingQuestion: null,
260	  planMode: false,
261	  activeTab: 'think',
262	  title: undefined,
263	  titleSource: undefined,
264	  inputDraft: "",
265	  think: createEmptyTabState(),
266	  do: createEmptyTabState(),
267	  setActiveTab: (tab: 'think' | 'do') => {
268	    const state = get();
269	    if (state.activeTab === tab) return;
270	
271	    set(produce((draft: ChatState) => {
272	      // Save full outgoing tab state
273	      syncTabStateFromFlat(draft, draft.activeTab);
274	      // Load incoming tab state into flat
275	      syncFlatStateFromTab(draft, tab);
276	      draft.activeTab = tab;
277	    }));
278	
279	    bridge.setActiveTab(tab);
280	  },
281	  get currentTabState() {
282	    const s = get();
283	    return s[s.activeTab];
284	  },
285	
286	  initTabs: async () => {
287	    console.log('[Store] initTabs starting');
288	    const restored = await bridge.restoreTabState();
289	    console.log('[Store] restored:', JSON.stringify(restored));
290	    const { setActiveTab, loadSession } = get();
291	
292	    // Fetch histories concurrently and catch any errors (e.g., deleted sessions)
293	    const [thinkRes, doRes] = await Promise.allSettled([
294	      restored.thinkSessionId ? bridge.loadSessionHistory(restored.thinkSessionId) : Promise.resolve(null),
295	      restored.doSessionId ? bridge.loadSessionHistory(restored.doSessionId) : Promise.resolve(null),
296	    ]);
297	
298	    const thinkEvents = thinkRes.status === 'fulfilled' ? thinkRes.value : null;
299	    const doEvents = doRes.status === 'fulfilled' ? doRes.value : null;
300	
301	    console.log('[Store] thinkEvents count:', thinkEvents?.length ?? 0);
302	    console.log('[Store] doEvents count:', doEvents?.length ?? 0);
303	
304	    // Load think silently
305	    if (restored.thinkSessionId && thinkEvents && thinkEvents.length > 0) {
306	      console.log('[Store] loading Think session silently');
307	      set({ activeTab: 'think' });
308	      await loadSession(restored.thinkSessionId, thinkEvents);
309	    }
310	
311	    // Load do silently
312	    if (restored.doSessionId && doEvents && doEvents.length > 0) {
313	      console.log('[Store] loading Do session silently');
314	      set({ activeTab: 'do' });
315	      await loadSession(restored.doSessionId, doEvents);
316	    }
317	
318	    const finalTab = restored.activeTab ?? 'think';
319	    console.log('[Store] setting final activeTab to:', finalTab);
320	
321	    // Ensure local state matches; bypass setActiveTab to avoid early-return if already set
322	    set(produce((draft: ChatState) => {
323	      draft.activeTab = finalTab;
324	      syncFlatStateFromTab(draft, finalTab);
325	    }));
326	
327	    // Explicitly sync to backend - critical on reload when backend activeTabs is empty
328	    bridge.setActiveTab(finalTab);
329	    console.log('[Store] initTabs complete');
330	  },
331	
332	  sendMessage: (text) => {
333	    const { draftMedia, isStreaming } = get();
334	    const { currentModel } = useSettingsStore.getState();
335	
336	    const readyMedia = draftMedia.filter((m) => m.dataUri).map((m) => m.dataUri!);
337	    const content = readyMedia.length > 0 ? Content.build(text, readyMedia) : text;
338	
339	    if (Content.isEmpty(content)) {
340	      return;
341	    }
342	
343	    // If streaming, enqueue instead of sending
344	    if (isStreaming) {
345	      get().enqueue(content, currentModel);
346	      set({ draftMedia: [] });
347	      return;
348	    }
349	
350	    // Clear draft and set streaming state on active tab
351	    set(
352	      produce((draft: ChatState) => {
353	        clearAllInlineErrors(draft[draft.activeTab]);
354	        draft.draftMedia = [];
355	        draft[draft.activeTab].isStreaming = true;
356	        draft[draft.activeTab].pendingInput = { content, model: currentModel };
357	        syncFlatStateFromTab(draft, draft.activeTab);
358	        draft.handshakeReceived = false;
359	      }),
360	    );
361	    useApprovalStore.getState().clearRequests();
362	
363	    doSend(get(), content, currentModel);
364	  },
365	
366	  retryLastMessage: () => {
367	    const { pendingInput, isStreaming } = get();
368	
369	    if (isStreaming || !pendingInput) {
370	      return;
371	    }
372	
373	    // Remove failed assistant message and user message
374	    set(
375	      produce((draft: ChatState) => {
376	        const tab = draft[draft.activeTab];
377	        clearAllInlineErrors(tab);
378	        tab.isStreaming = true;
379	        const lastAssistant = tab.messages.at(-1);
380	        if (lastAssistant?.role === "assistant" && lastAssistant.inlineError) {
381	          tab.messages.pop();
382	          if (tab.messages.at(-1)?.role === "user") {
383	            tab.messages.pop();
384	          }
385	        }
386	        syncFlatStateFromTab(draft, draft.activeTab);
387	        draft.handshakeReceived = false;
388	      }),
389	    );
390	    useApprovalStore.getState().clearRequests();
391	
392	    doSend(get(), pendingInput.content, pendingInput.model);
393	  },
394	
395	  processEvent: (event) => {
396	    // Clear handshake timeout on receiving valid response
397	    if (event.type === "TurnBegin" || event.type === "StepBegin" || event.type === "ContentPart") {
398	      clearHandshakeTimer();
399	      set({ handshakeReceived: true });
400	    }
401	
402	    set(
403	      produce((draft: ChatState) => {
404	        // Route event to correct tab by explicit mode, then sessionId, then active tab fallback
405	        const targetTab = getTargetTab(event as any, {
406	          activeTab: draft.activeTab,
407	          thinkSessionId: draft.think.sessionId,
408	          doSessionId: draft.do.sessionId,
409	        });
410	        const activeTab = draft.activeTab;
411	
412	        // If the event targets the inactive tab, swap its state into the flat
413	        // scratch space so legacy handlers (which mutate flat state) operate on
414	        // the right tab. Then swap back.
415	        if (targetTab !== activeTab) {
416	          syncTabStateFromFlat(draft, activeTab);
417	          syncFlatStateFromTab(draft, targetTab);
418	        }
419	
420	        processEvent(draft, event);
421	
422	        syncTabStateFromFlat(draft, targetTab);
423	
424	        if (targetTab !== activeTab) {
425	          syncFlatStateFromTab(draft, activeTab);
426	        }
427	
428	        // Invariant: flat state must always reflect the active tab
429	        if (draft.messages !== draft[draft.activeTab].messages) {
430	          console.warn(
431	            `[chat.store invariant] messages mismatch: flat state points to ${draft.messages === draft.think.messages ? 'think' : draft.messages === draft.do.messages ? 'do' : 'unknown'}, activeTab=${draft.activeTab}`,
432	          );
433	        }
434	        if (draft.isStreaming !== draft[draft.activeTab].isStreaming) {
435	          console.warn(
436	            `[chat.store invariant] isStreaming mismatch: flat=${draft.isStreaming}, ${draft.activeTab}.isStreaming=${draft[draft.activeTab].isStreaming}`,
437	          );
438	        }
439	        if (draft.think.messages.some((m: any) => (m as any)._sessionId && (m as any)._sessionId === draft.do.sessionId)) {
440	          console.warn(`[chat.store invariant] Think tab contains messages from Do session ${draft.do.sessionId}`);
441	        }
442	        if (draft.do.messages.some((m: any) => (m as any)._sessionId && (m as any)._sessionId === draft.think.sessionId)) {
443	          console.warn(`[chat.store invariant] Do tab contains messages from Think session ${draft.think.sessionId}`);
444	        }
445	      }),
446	    );
447	
448	    // Auto-send next queued item when streaming ends (complete, abort, or error).
449	    // history_restored does NOT trigger auto-send — the user is reviewing history.
450	    if (event.type === "stream_complete" || event.type === "stream_aborted" || event.type === "error") {
451	      const { queue, isStreaming: stillStreaming } = get();
452	      if (!stillStreaming && queue.length > 0) {
453	        setTimeout(() => get().sendNextQueued(), 50);
454	      }
455	    }
456	  },
457	
458	  loadSession: async (sessionId, events, titleInfo) => {
459	    clearHandshakeTimer();
460	    
461	    // Abort any ongoing stream when switching sessions
462	    const { isStreaming: wasStreaming } = get();
463	    if (wasStreaming) {
464	      await bridge.abortChat();
465	    }
466	    
467	    set(produce((draft: ChatState) => {
468	      // Reset active tab state
469	      draft[draft.activeTab] = createEmptyTabState();
470	      draft[draft.activeTab].sessionId = sessionId;
471	      draft[draft.activeTab].title = titleInfo?.title;
472	      draft[draft.activeTab].titleSource = titleInfo?.titleSource;
473	      // Sync flat state from active tab
474	      syncFlatStateFromTab(draft, draft.activeTab);
475	      // Reset globals
476	      draft.handshakeReceived = false;
477	      draft.draftMedia = [];
478	      draft.queue = [];
479	    }));
480	    useApprovalStore.getState().clearRequests();
481	    bridge.clearTrackedFiles();
482	
483	    for (const event of events) {
484	      // Inject sessionId for proper tab routing during history load
485	      (event as any)._sessionId = sessionId;
486	      get().processEvent(event);
487	    }
488	
489	    // All steps are finished when loading from history
490	    set(
491	      produce((draft: ChatState) => {
492	        for (const msg of draft.messages) {
493	          if (msg.steps) {
494	            for (const step of msg.steps) {
495	              for (const item of step.items) {
496	                if (item.type === "text" || item.type === "thinking") {
497	                  item.finished = true;
498	                }
499	              }
500	            }
501	          }
502	        }
503	        draft.isStreaming = false;
504	        draft.isCompacting = false;
505	        draft.pendingQuestion = null;
506	        // Sync back to active tab
507	        syncTabStateFromFlat(draft, draft.activeTab);
508	      }),
509	    );
510	    useApprovalStore.getState().clearRequests();
511	  },
512	
513	  startNewConversation: async () => {
514	    clearHandshakeTimer();
515	    
516	    // Abort any ongoing stream before starting new conversation
517	    const { isStreaming: wasStreaming } = get();
518	    if (wasStreaming) {
519	      bridge.abortChat();
520	    }
521	    
522	    await bridge.resetSession();
523	    await bridge.clearTrackedFiles();
524	    set(produce((draft: ChatState) => {
525	      draft[draft.activeTab] = createEmptyTabState();
526	      syncFlatStateFromTab(draft, draft.activeTab);
527	      draft.handshakeReceived = false;
528	      draft.draftMedia = [];
529	      draft.queue = [];
530	    }));
531	    useApprovalStore.getState().clearRequests();
532	  },
533	
534	  abort: () => {
535	    clearHandshakeTimer();
536	    bridge.abortChat();
537	    set(produce((draft: ChatState) => {
538	      draft[draft.activeTab].pendingQuestion = null;
539	      syncFlatStateFromTab(draft, draft.activeTab);
540	    }));
541	    useApprovalStore.getState().clearRequests();
542	  },
543	
544	  addDraftMedia: (id, dataUri) => {
545	    set((s) => ({ draftMedia: [...s.draftMedia, { id, dataUri }] }));
546	  },
547	
548	  updateDraftMedia: (id, dataUri) => {
549	    set((s) => ({
550	      draftMedia: s.draftMedia.map((m) => (m.id === id ? { ...m, dataUri } : m)),
551	    }));
552	  },
553	
554	  removeDraftMedia: (id) => {
555	    set((s) => ({ draftMedia: s.draftMedia.filter((m) => m.id !== id) }));
556	  },
557	
558	  clearDraftMedia: () => {
559	    set({ draftMedia: [] });
560	  },
561	
562	  getMediaInConversation: () => {
563	    const { messages, draftMedia } = get();
564	
565	    let hasImage = false;
566	    let hasVideo = false;
567	
568	    for (const item of draftMedia) {
569	      if (!item.dataUri) {
570	        continue;
571	      }
572	      if (item.dataUri.startsWith("data:image/")) {
573	        hasImage = true;
574	      } else if (item.dataUri.startsWith("data:video/")) {
575	        hasVideo = true;
576	      }
577	    }
578	
579	    for (const msg of messages) {
580	      if (Content.hasImages(msg.content)) {
581	        hasImage = true;
582	      }
583	      if (Content.hasVideos(msg.content)) {
584	        hasVideo = true;
585	      }
586	      if (hasImage && hasVideo) {
587	        break;
588	      }
589	    }
590	
591	    return { hasImage, hasVideo };
592	  },
593	
594	  hasProcessingMedia: () => {
595	    return get().draftMedia.some((m) => !m.dataUri);
596	  },
597	
598	  rollbackInput: (content) => {
599	    const { currentModel } = useSettingsStore.getState();
600	    set(produce((draft: ChatState) => {
601	      draft[draft.activeTab].pendingInput = { content, model: currentModel };
602	      syncFlatStateFromTab(draft, draft.activeTab);
603	    }));
604	  },
