608	    if (!pendingQuestion) return;
609	    await bridge.respondQuestion(pendingQuestion.id, pendingQuestion.id, answers);
610	    set(produce((draft: ChatState) => {
611	      draft[draft.activeTab].pendingQuestion = null;
612	      syncFlatStateFromTab(draft, draft.activeTab);
613	    }));
614	  },
615	
616	  setTitle: (sessionId, title, source) => {
617	    if (!sessionId) return;
618	    set(
619	      produce((draft: ChatState) => {
620	        const targetTab =
621	          draft.think.sessionId === sessionId ? 'think' :
622	          draft.do.sessionId === sessionId ? 'do' :
623	          draft.activeTab;
624	
625	        draft[targetTab].title = title;
626	        draft[targetTab].titleSource = source;
627	        if (targetTab === draft.activeTab) {
628	          draft.title = title;
629	          draft.titleSource = source;
630	        }
631	      }),
632	    );
633	  },
