635	  renameSession: async (sessionId, newTitle) => {
636	    if (!sessionId) return;
637	    const trimmed = newTitle.trim();
638	    const source: TitleSource = trimmed ? 'user' : 'fallback';
639	    const title = trimmed;
640	
641	    get().setTitle(sessionId, title || "Untitled", source);
642	    await bridge.writeSessionMetadata(sessionId, title, source);
643	  },
644	
645	  setInputDraft: (text) => {
646	    set({ inputDraft: text });
647	  },
648	
